compute_correlations &lt;- function(df, covariate, year_max, city) {
  cases_df &lt;- df |&gt;
    filter(year &lt;= year_max, month &gt;= 8, month &lt;= 11) |&gt;
    group_by(year) |&gt;
    summarize(cases = sum(PF))

  covariate_df &lt;- df |&gt; filter(year &lt;= year_max) |&gt;
   select(year, month, all_of(covariate)) |&gt;
   rename(cov = all_of(covariate))
  result_df &lt;- c()
  for(i in 1:9){
    for(j in i:9){
      cov_df &lt;- covariate_df |&gt;
        filter(month &gt;= i, month &lt;= j) |&gt;
        group_by(year) |&gt;
        summarize(cov = mean(cov))

      joined &lt;- inner_join(cases_df, cov_df, by = "year")
      val &lt;- cor(joined$cases, joined$cov)
      res &lt;- tibble_row(city = city, covariate = covariate, start_window = i,
       end_window = j, correlation = val)

      result_df &lt;- rbind(result_df, res)
    }
  }

  return(result_df)
}
